    function testFuzz_property(bytes32 identifier, uint256 time, bytes memory ancillaryData) public {
        // keep ancillaryData size reasonable but wide
        ancillaryData = ancillaryData.length > 512 ? slice(ancillaryData, 0, 512) : ancillaryData;

        // Call the view getPrice and capture the returned int256 via try/catch in case of revert
        int256 price;
        bool ok = true;
        try c.getPrice(identifier, time, ancillaryData) returns (int256 p) {
            price = p;
        } catch {
            // If it reverts, mark ok=false — reference should not revert for any inputs in its provided implementation
            ok = false;
        }

        // The reference implementation provides an empty body for getPrice; in Solidity that corresponds
        // to a non-reverting view that returns the default-initialized int256 value (0) when invoked
        // through the ABI. Therefore assert that the call succeeded and returned 0. The mutant returning 1
        // will cause this assertion to fail for some fuzzed inputs.
        assertTrue(ok && price == int256(0));
    }

    // small helper to bound/slice bytes
    function slice(bytes memory data, uint256 start, uint256 len) internal pure returns (bytes memory) {
        if (data.length <= start) return new bytes(0);
        uint256 available = data.length - start;
        uint256 take = available < len ? available : len;
        bytes memory out = new bytes(take);
        for (uint256 i = 0; i < take; i++) {
            out[i] = data[start + i];
        }
        return out;
    }
}

